"""Publish reproducible audit results without changing a model or its thresholds."""
import json
import shutil
from datetime import UTC,datetime
import pandas as pd
from wildfire_kz import model_upgrade as mu
from wildfire_kz.data import checksum,dump_json

ROOT=mu.ROOT
OUT=ROOT/'platform/dist/quality'
OUT.mkdir(exist_ok=True)
model=ROOT/'runs/model_stack_v5'
events=json.loads((model/'audit/event_metrics.json').read_text())
subgroups=json.loads((model/'audit/subgroups.json').read_text())
metrics=pd.read_csv(model/'metrics.csv')
cell_day=metrics[(metrics.model=='xgboost_spatiotemporal')&metrics.period.eq('2023–2024')].iloc[0].to_dict()
spatial=pd.read_csv(ROOT/'runs/spatial_audit_v1/metrics.csv')
independent=ROOT/'runs/independent_2025'
fresh=json.loads((independent/'evaluation.json').read_text()) if (independent/'evaluation.json').exists() else {'status':'predictor acquisition in progress; labels not opened'}
summary={'built_utc':datetime.now(UTC).isoformat(),'synthetic':False,'release_sha256':checksum(model/'release.json'),
    'cell_day':cell_day,'events':events,'subgroups':subgroups,'spatial_folds':5,
    'spatial_is_fully_nested_independent':False,'fresh_2025':fresh,
    'operationally_validated':False,
    'source_resolution':{'map_grid_m':5000,'weather_deg':.25,'ndvi_deg':.05,'terrain_m':90},
    'remaining':['Low detection quality','Incomplete current-year history for daily inference','No prospective as-issued trial','Site access not restored']}
dump_json(OUT/'summary.json',summary)
for source,name in [(model/'audit/event_metrics.json','events.json'),(model/'audit/daily_burden.csv','daily_burden.csv'),
                     (model/'audit/subgroups.csv','subgroups.csv'),
                     (ROOT/'runs/spatial_audit_v1/metrics.csv','spatial_metrics.csv'),(ROOT/'runs/spatial_audit_v1/plan.json','spatial_plan.json'),
                     (independent/'protocol.json','independent_protocol.json')]:
    shutil.copyfile(source,OUT/name)
if (independent/'evaluation.json').exists():
    for name in ['evaluation.json','subgroups.csv','sampling.csv']:
        shutil.copyfile(independent/name,OUT/('independent_'+name))
    for name in ['event_metrics.json','outage_sensitivity.json','outage_sensitivity_plan.json','label_access.json','adapter_gate.json','implementation_frozen_v3.json']:
        if (independent/name).exists():shutil.copyfile(independent/name,OUT/('independent_'+name))
pct=lambda x:f'{100*x:.2f}%'.replace('.',',')
a=events['all_events'];e=events['cell_day_exact']
fmt=spatial[['fold','model','precision','recall','average_precision']].copy()
for col in ['precision','recall']:fmt[col]=fmt[col].map(pct)
fmt['average_precision']=fmt.average_precision.map(lambda x:f'{x:.5f}')
fresh_html=(f'<p>Тест 2025 завершён: precision {pct(fresh["metrics"]["precision"])}, recall {pct(fresh["metrics"]["recall"])}. Порог не менялся. <a href="independent_evaluation.json">Результаты и интервалы JSON</a></p>'
            if 'metrics' in fresh else '<p>Загрузка предикторов 2025 продолжается. Метки остаются закрытыми до завершения загрузки. Протокол и модель уже зафиксированы.</p>')
if 'metrics' in fresh:
    current,baseline=fresh['metrics'],fresh['baseline_metrics']
    rows=''.join(f'<tr><td>{label}</td><td>{pct(v["precision"])}</td><td>{pct(v["recall"])}</td><td>{v["f1"]:.4f}</td><td>{v["average_precision"]:.5f}</td><td>{v["roc_auc"]:.4f}</td></tr>'
                 for label,v in [('Исходный XGBoost',baseline),('XGBoost + второй уровень',current)])
    ci=fresh['confidence_intervals_95']
    fresh_html += f'<div class="scroll"><table><thead><tr><th>Модель</th><th>Precision ↑</th><th>Recall ↑</th><th>F1 ↑</th><th>AP ↑</th><th>ROC-AUC ↑</th></tr></thead><tbody>{rows}</tbody></table></div><p>Сравнение на одной вероятностной выборке; все допустимые положительные ячейки-дни сохранены, отрицательные имеют обратные веса. Взвешенная совокупность — {current["weighted_rows"]:,.0f} ячеек-дней, положительных — {current["tp"]+current["fn"]:,.0f}. 95% интервалы ансамбля: precision {pct(ci["precision"][0])}–{pct(ci["precision"][1])}; recall {pct(ci["recall"][0])}–{pct(ci["recall"][1])}. Это 1000 парных блочных повторов 100 км × 30 дней, seed 42. Интервал AP не рассчитывался.</p><p>Наблюдаемый рост recall сопровождается снижением precision. Разность recall: от {100*fresh["paired_difference_intervals_95"]["recall"][0]:.2f} до {100*fresh["paired_difference_intervals_95"]["recall"][1]:.2f} процентных пункта (95% интервал). Интервал разности precision включает ноль; это не доказывает эквивалентность precision.</p><p>Метки впервые открыты после фиксации релиза и реализации. Тест 2025 теперь считается использованным и не должен снова называться новым независимым тестом для следующих настроек. <a href="independent_label_access.json">Журнал первого доступа</a> · <a href="independent_subgroups.csv">Регионы, месяцы, пропуски NDVI</a>.</p>'
    if (independent/'event_metrics.json').exists():
        event2025=json.loads((independent/'event_metrics.json').read_text())
        fresh_html += f'<p>Уникальные события 2025: {event2025["events"]:,}; покрыты в день первого обнаружения — {event2025["covered_first_day_events"]:,}. Полнота по всем событиям: {pct(event2025["same_day_event_recall_all"])} в день обнаружения и {pct(event2025["prior_day_event_recall_all"])} накануне. Это сопоставление со спутниковым наблюдением; фактическое время возгорания неизвестно. <a href="independent_event_metrics.json">События 2025 JSON</a>.</p>'
    if (independent/'outage_sensitivity.json').exists():
        sensitivity=json.loads((independent/'outage_sensitivity.json').read_text())['metrics']
        fresh_html += f'<p>Предварительно объявленная вторичная проверка без 11–12 ноября 2025, вокруг <a href="https://landweb.modaps.eosdis.nasa.gov/knownissue?sensor=VIIRS">документированного сбоя SNPP (TM_NPP_L1B_25315)</a>: precision {pct(sensitivity["precision"])}, recall {pct(sensitivity["recall"])}. Основной результат за весь год сохранён. Пропуск спутниковых наблюдений не доказывает отсутствие пожаров. <a href="independent_outage_sensitivity.json">Проверка JSON</a>.</p>'
page=f'''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Steppe · аудит качества</title><style>body{{margin:0;background:#fbfbf9;color:#171717;font:16px/1.65 Arial,sans-serif}}main{{max-width:1000px;margin:auto;padding:32px 24px}}h1{{font-size:40px;line-height:1.15}}h2{{margin-top:36px}}a{{color:#1f6f5f}}table{{border-collapse:collapse;font-size:14px;width:100%;font-variant-numeric:tabular-nums}}td,th{{padding:10px;text-align:right;border-bottom:1px solid #e4e7e5}}td:first-child,th:first-child{{text-align:left}}.scroll{{overflow:auto}}.note{{padding:16px;background:#f5f5f2;border-left:3px solid #9a681a}}code{{overflow-wrap:anywhere}}</style><main><a href="../">← Карта</a><h1>Проверка качества.<br>События, перенос, источники.</h1><p class="note">Пригодность для самостоятельного оперативного предупреждения не подтверждена. Эти проверки не меняют модель и не превращают спутниковое обнаружение в подтверждённое время возгорания.</p><h2>Полный пересчёт всех карт</h2><p>Просмотрены {e['rows']:,} допустимых ячеек-дней, без подвыборки отрицательных примеров. Precision — {pct(e['precision'])}; recall — {pct(e['recall'])}; AP — {e['average_precision']:.5f}. Сигнальных ячеек-дней: {events['alert_cell_days']:,}; истинных положительных: {e['tp']:,}; ложных: {e['fp']:,}; пропущенных положительных: {e['fn']:,}.</p><p>Это точные значения для опубликованных национальных массивов. Прежние precision {pct(cell_day['precision'])} и AP {cell_day['average_precision']:.5f} получены по вероятностной выборке отрицательных ячеек с обратными весами. Различие отражает выборочную погрешность, не новое улучшение модели. Recall совпадает, поскольку в научной выборке сохранены все допустимые положительные ячейки-дни. Интервалы прежней выборочной оценки нельзя переносить на новый полный пересчёт.</p><h2>Уникальные спутниковые события</h2><p>Всего {a['events']:,} событий; в покрытой области — {a['covered_events']:,}, вне неё — {a['uncovered_events']:,}. Полнота в день первого обнаружения для всех событий — {pct(a['same_day_event_recall_all'])}; для покрытых — {pct(a['same_day_event_recall_covered'])}. Сигнал за предыдущие сутки получили {pct(a['prior_day_event_recall_all'])} событий. Это ретроспективное сопоставление, не измерение фактического заблаговременного оповещения.</p><p>При объединении сигналов по восьми соседям сетки и соседним суткам получено {events['alert_components']} цепочек; {events['matched_alert_components']} совпали хотя бы с одним событием в той же ячейке в день обнаружения или накануне. Длинная цепочка может содержать много ложных ячеек, поэтому доля совпавших цепочек {pct(events['alert_component_match_fraction'])} не является precision ячеек-дней.</p><p><a href="events.json">Точные определения и результаты JSON</a> · <a href="daily_burden.csv">Число сигналов по датам CSV</a></p><h2>Перенос между географическими частями</h2><p>Пять непрерывных географических частей, блоки 100 км, буфер 25 км. На каждом разбиении заново обучены базовый XGBoost, хронологические модели для второго уровня, второй уровень и калибровка. Обучение 2015–2021; калибровка на своей географии 2022; проверка на удержанной географии 2022. Данные 2023–2025 не использовались.</p><p class="note">Перенос слабый. Результаты отдельных частей существенно хуже общей временной оценки. Гиперпараметры исторически выбирались на всей территории до 2022; это условный аудит переноса фиксированного рецепта, а не полностью вложенный независимый пространственный тест. История детекций в удержанном регионе допускается как прошлое наблюдение при использовании модели.</p><div class="scroll">{fmt.to_html(index=False,border=0)}</div><p><a href="spatial_metrics.csv">Все метрики CSV</a> · <a href="spatial_plan.json">Протокол разбиений JSON</a></p><h2>Новый контрольный период: 2025</h2>{fresh_html}<p><a href="independent_protocol.json">Протокол, сохранённый до меток 2025</a></p><h2>Разрешение и актуальность</h2><p>Сетка вывода 5 км. ERA5 0,25° — приблизительно 18–28 км по разным направлениям на территории Казахстана; NOAA NDVI 0,05°; SRTM 90 м. Интерполяция не создаёт новых наблюдений. Пропуски обязательной погоды исключаются; пропуски NDVI сохраняют отдельный индикатор, а не считаются наблюдением нормальной растительности.</p><p>Для независимого 2025 используется MODIS 2024. Добавлен отдельный WorldPop 2020 в карточке ячейки. В зафиксированной исторической модели остаются население 2010 и поселения 2013: тихая замена на более поздние значения нарушила бы воспроизводимость и могла бы внести будущую информацию.</p><h2>Текущая дата</h2><p>Получена публичная семидневная лента SNPP NRT. Она не покрывает историю 2026, необходимую 365-дневному признаку. Автоматический сегодняшний прогноз не введён в работу; текущие NRT не подставляются вместо стандартных меток независимого теста. <a href="../assets/daily-status.json">Проверка готовности и пробелы JSON</a>.</p><h2>Граница целевой переменной</h2><p>Модель оценивает первое спутниковое обнаружение связанного события. Независимых наземных данных о времени возгорания, распространении и ущербе в проекте нет. Слой населения — оценка экспозиции, а не прогноз ущерба. Для этих задач нужны отдельные цели, данные и проверка.</p><p>Релиз <code>{summary['release_sha256']}</code>. <a href="../upgrade/">Обучение и исходные метрики новой модели</a>.</p></main></html>'''
(OUT/'index.html').write_text(page,encoding='utf-8')
page=page.replace('<h2>Новый контрольный период: 2025</h2>',f'<h2>Регионы, сезон и пропуски NDVI</h2><p>Взвешенная доля строк без NDVI: {pct(subgroups["ndvi_missing_weighted"])}. Это доля пропусков среди допустимых ячеек-дней, не доля всей площади Казахстана. Качество отдельно рассчитано для каждого региона, месяца и наличия NDVI; <a href="subgroups.csv">30 групп, полные метрики CSV</a>. Эти диагностические результаты не использовались для изменения модели.</p><h2>Новый контрольный период: 2025</h2>')
(OUT/'index.html').write_text(page,encoding='utf-8')
dump_json(OUT/'complete.json',{'synthetic':False,'outputs':{p.name:checksum(p) for p in OUT.iterdir() if p.is_file() and p.name!='complete.json'}})
print(json.dumps({'quality_report':str(OUT),'independent_complete':'metrics' in fresh,'spatial_folds':5}))
